import {mountDock} from './afterlight-dock.js';
import {createStation} from '../shared/station-art.js';
import {T,engine,batchStatic,box,sphere,cylinder,line,label} from '../shared/engine.js';
import {shell,load,save,toast,modal,lifecycle,tone,bindHold,clamp} from '../shared/core.js';
export function mount(){if(load('afterlight',{}).complete)return mountDock();shell('Afterlight','SECTOR 07 · SILENT ORBIT');const e=engine({sky:0x071421,fog:160}),s=e.scene;const art=createStation(e),{fuse,screen,bridge,beam,recorder,astronaut}=art;
const initial={x:2,fuse:false,power:false,complete:false,log:false,checkpoint:2,relays:[0,0,0]};let state=load('afterlight',initial);if(state.complete)state={...initial,relays:[0,0,0]};let saveTime=0,coyote=.12,jumpBuffer=0,vx=0;let x=state.x,y=0,vy=0,left=false,right=false,grounded=true,timer=0,checkpoint=state.checkpoint??(state.power?29:2),finished=false;fuse.visible=!state.fuse;bridge.visible=state.power;recorder.visible=!state.log;
document.querySelector('#controls').innerHTML='<div class="control-panel"><button class="hold" id="left" aria-label="Move left">‹</button><button class="hold" id="right" aria-label="Move right">›</button></div><div class="control-note">Move · jump · inspect.<br>Watch the pulse before crossing.</div><div class="control-panel"><button id="interact">Inspect</button><button class="hold primary" id="jump" aria-label="Jump">↑</button></div>';const persist=()=>{state.x=grounded?x:checkpoint;state.checkpoint=checkpoint;save('afterlight',state)};for(const [id,set]of [['left',v=>left=v],['right',v=>right=v]])bindHold(document.querySelector('#'+id),()=>set(true),()=>set(false));const jump=()=>{if(!life.paused()){jumpBuffer=.16}};document.querySelector('#jump').onpointerdown=jump;
function relay(){const d=modal('The relay console',`<p>${state.fuse?'The replacement cell is seated.':'A power cell is missing. Look near the start of the gantry.'} The maintenance stencil on the bulkhead gives the three relay positions.</p><div style="display:flex;gap:12px;justify-content:center;margin:24px 0">${state.relays.map((n,i)=>`<button class="relay" data-i="${i}" style="font-size:30px;width:70px;height:80px;color:#8de1df">${n}</button>`).join('')}</div><p id="feedback">Tap each relay to rotate through positions 0–3.</p>`,[{text:'Restore power',close:false,action:()=>{if(!state.fuse){d.querySelector('#feedback').textContent='Find the power cell first.';return}if(state.relays.join('')==='213'){state.power=true;checkpoint=29;bridge.visible=true;screen.material.emissive.setHex(0x47c6a0);persist();d.remove();toast('Power restored · the bridge is extended');tone(660,.3)}else d.querySelector('#feedback').textContent='Relay mismatch. Read the 2 • 1 • 3 stencil.'}},{text:'Back'}]);d.querySelectorAll('.relay').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;state.relays[i]=(state.relays[i]+1)%4;b.textContent=state.relays[i];persist();tone(300+i*90,.08)})}
function interact(){if(life.paused())return;if(Math.abs(x-11)<3&&!state.fuse){state.fuse=true;fuse.visible=false;persist();toast('Power cell collected · find the relay console');tone(700,.18)}else if(Math.abs(x-28)<3){relay()}else if(Math.abs(x-64)<3&&!state.log){state.log=true;recorder.visible=false;persist();modal('The last transmission','<p>“Sector 07 evacuated. We left the relay positions on the bulkhead. The security grid is cycling on reserve power. If you find this recorder, bring it home.”</p><p><strong>Flight recorder recovered.</strong></p>')}else if(Math.abs(x-73)<3){if(!state.power){toast('The airlock needs power from the relay console');return}finished=true;state.complete=true;persist();modal('A light in the dark',`<p>The airlock cycles. Your suit catches the first light of the planet below.</p><p><strong>Sector 07 complete.</strong> The power is restored and your escape route is open.</p><p>${state.log?'Flight recorder recovered.':'A flight recorder remains near the airlock.'}</p>`,[{text:'Continue to orbital docks',action:()=>location.reload()},{text:'Return to Studio',action:()=>location.hash=''},{text:'Replay sector',action:()=>{save('afterlight',initial);save('afterlight:dock',null);location.reload()}}])}else toast(x<20?'A loose power cell is glowing near the start.':x<40?'The console is beside the relay stencil.':x<58?'The security beam pulses. Cross while it is off.':'The airlock is ahead.')}
document.querySelector('#interact').onclick=interact;const kd=ev=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','a','d','w','e'].includes(ev.key)){ev.preventDefault();if(['a','ArrowLeft'].includes(ev.key))left=true;if(['d','ArrowRight'].includes(ev.key))right=true;if(['w','ArrowUp',' '].includes(ev.key))jump();if(ev.key==='e'&&!ev.repeat)interact()}};const ku=ev=>{if(['a','ArrowLeft'].includes(ev.key))left=false;if(['d','ArrowRight'].includes(ev.key))right=false};addEventListener('keydown',kd);addEventListener('keyup',ku);const release=()=>{left=right=false;vx=0;jumpBuffer=0};addEventListener('blur',release);const life=lifecycle({pause:release,reset:()=>save('afterlight',initial)});if(!load('intro:afterlight',false))modal('Wake up, traveller',`<p>The station is running on emergency power. Recover a power cell, repair the relay, and reach the airlock.</p><p>Use the arrows to move, ↑ to jump, and <strong>Inspect</strong> near objects. On a keyboard: A/D, Space, and E.</p>`,[{text:'Enter Sector 07',action:()=>save('intro:afterlight',true)}]);e.start((dt,t)=>{if(!life.paused()&&!finished){timer+=dt;const move=(right?1:0)-(left?1:0),old=x;coyote=grounded?.12:Math.max(0,coyote-dt);jumpBuffer=Math.max(0,jumpBuffer-dt);if(jumpBuffer>0&&coyote>0){vy=7.7;grounded=false;jumpBuffer=coyote=0;tone(240,.07)}vx+=(move*6.5-vx)*(1-Math.exp(-dt*(grounded?14:7)));x=clamp(x+vx*dt,1,74);for(const b of [{x:17,w:1.45,h:1.65},{x:59,w:1.3,h:1.15}])if(Math.abs(x-b.x)<b.w&&y<b.h)x=old;vy-=16*dt;y+=vy*dt;const gap=x>35.5&&x<40.5&&!state.power;const floor=Math.abs(x-17)<1.35?1.7:Math.abs(x-59)<1.2?1.2:0;if(!gap&&y<=floor&&vy<=0){y=floor;vy=0;grounded=true}else grounded=false;if(y<-5){x=checkpoint;y=0;vy=vx=0;toast('Emergency tether recovered you · try again')}const beamOn=timer%4.5<2.5;beam.visible=beamOn;if(beamOn&&Math.abs(x-49)<.6){x=checkpoint;y=0;vy=vx=0;toast('Security pulse · wait until the beam switches off');tone(120,.2)}if(x>54&&checkpoint<55){checkpoint=55;persist();toast('Airlock approach · checkpoint saved')}saveTime+=dt;if(grounded&&saveTime>.75){persist();saveTime=0}}recorder.rotation.y=t*.7;recorder.position.y=1.1+Math.sin(t*2)*.12;fuse.rotation.y=t;fuse.position.y=1+Math.sin(t*2)*.12;art.update({x,y,vx,grounded,t,power:state.power});const portrait=innerHeight>innerWidth;const cam=new T.Vector3(x+(portrait?2:3),portrait?4.6:3.5,portrait?18.5:13.8);e.camera.position.lerp(cam,1-Math.exp(-dt*5));e.camera.lookAt(x+(portrait?1:3),1.5,0);document.querySelector('#stat').textContent=!state.fuse?'Find the power cell':!state.power?'Repair the relay console':x<53?'Security beam: '+(timer%4.5<2.5?'ACTIVE · '+(2.5-timer%4.5).toFixed(1)+' s':'CLEAR · '+(4.5-timer%4.5).toFixed(1)+' s'):'Airlock approach · checkpoint saved';document.querySelector('#interact').textContent=Math.abs(x-11)<3&&!state.fuse?'Collect':Math.abs(x-28)<3?'Console':Math.abs(x-64)<3&&!state.log?'Recorder':Math.abs(x-73)<3?'Airlock':'Inspect'});return {dispose(){persist();life.dispose();art.dispose();e.dispose();removeEventListener('keydown',kd);removeEventListener('keyup',ku);removeEventListener('blur',release)}}}
